import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyBaoTri = () => {
    const now = new Date();
    const [selectedDate, setSelectedDate] = useState(now.getDate());
    const [selectedMonth, setSelectedMonth] = useState(now.getMonth() + 1);
    const [selectedYear, setSelectedYear] = useState(now.getFullYear());
    const [requests, setRequests] = useState([]);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        fetchData();
    }, [selectedDate, selectedMonth, selectedYear]);

    const fetchData = () => {
        setLoading(true);
        const allData = JSON.parse(localStorage.getItem('maintenance_db') || '[]');
        const filtered = allData.filter(item => 
            item.day === selectedDate && item.month === selectedMonth && item.year === selectedYear
        );
        // Mô phỏng chờ Backend giống XemHoaDon
        setTimeout(() => {
            setRequests(filtered);
            setLoading(false);
        }, 300);
    };

    const updateStatus = (id, newStatus) => {
        const allData = JSON.parse(localStorage.getItem('maintenance_db') || '[]');
        const updated = allData.map(req => req.id === id ? { ...req, status: newStatus } : req);
        localStorage.setItem('maintenance_db', JSON.stringify(updated));
        fetchData();
    };

    return (
        <div style={containerStyle} className="glass-card">
            {/* Header: Chỉ mờ phần nền đen 0.3 giống XemHoaDon */}
            <div style={headerStyle}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '20px' }}>🛠 QUẢN LÝ BẢO TRÌ</h2>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select value={selectedDate} onChange={(e) => setSelectedDate(Number(e.target.value))} style={selectStyle}>
                        {Array.from({length:31},(_,i)=><option key={i+1} value={i+1}>Ngày {i+1}</option>)}
                    </select>
                    <select value={selectedMonth} onChange={(e) => setSelectedMonth(Number(e.target.value))} style={selectStyle}>
                        {[...Array(12)].map((_, i) => <option key={i+1} value={i+1}>Tháng {i+1}</option>)}
                    </select>
                </div>
            </div>

            <div style={contentWrapperStyle}>
                {/* Khối nội dung: TRẮNG ĐẶC, BÓNG ĐẬM giống mainFormStyle */}
                <div style={mainTableCard}>
                    {loading ? (
                        <div style={statusMsg}>Đang kiểm tra dữ liệu...</div>
                    ) : requests.length > 0 ? (
                        <div style={{ animation: 'fadeIn 0.4s', height: '100%', display: 'flex', flexDirection: 'column' }}>
                            <div style={{ overflowY: 'auto', flex: 1 }} className="custom-scrollbar">
                                <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                                    <thead style={{ position: 'sticky', top: 0, backgroundColor: '#fff', zIndex: 1 }}>
                                        <tr style={{ textAlign: 'left', borderBottom: '2px solid #fdf3f3' }}>
                                            <th style={thStyle}>PHÒNG</th>
                                            <th style={thStyle}>SỰ CỐ</th>
                                            <th style={thStyle}>TRẠNG THÁI</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {requests.map(req => (
                                            <tr key={req.id} style={{ borderBottom: '1px solid #eee' }}>
                                                <td style={tdRoom}>{req.room}</td>
                                                <td style={tdIssue}>
                                                    <div style={{ fontWeight: 'bold' }}>{req.title}</div>
                                                    <div style={{ fontSize: '12px', color: '#777' }}>{req.issue}</div>
                                                </td>
                                                <td style={{ padding: '15px' }}>
                                                    <select 
                                                        value={req.status} 
                                                        onChange={(e) => updateStatus(req.id, e.target.value)}
                                                        style={statusSelectStyle(req.status)}
                                                    >
                                                        <option value="pending">Chờ xử lý</option>
                                                        <option value="processing">Đang sửa</option>
                                                        <option value="completed">Xong</option>
                                                    </select>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    ) : (
                        <div style={emptyState}>
                            <div style={{ fontSize: '50px', marginBottom: '10px' }}>📅</div>
                            <div>Không có yêu cầu nào</div>
                        </div>
                    )}
                </div>
            </div>
            <style>{`
                @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
                .custom-scrollbar::-webkit-scrollbar { width: 4px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #eee; border-radius: 10px; }
            `}</style>
        </div>
    );
};

// --- STYLES COPY CHUẨN TỪ XEMHOADON ---
const containerStyle = { flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', backgroundPosition: 'center', height: 'calc(100vh - 120px)', overflow: 'hidden' };
const headerStyle = { padding: '20px 30px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'rgba(0,0,0,0.3)' };
const selectStyle = { padding: '8px 12px', borderRadius: '10px', border: 'none', fontWeight: 'bold', cursor: 'pointer' };
const contentWrapperStyle = { flex: 1, display: 'flex', justifyContent: 'center', alignItems: 'center', padding: '20px' };

// Chỉnh lại mainTableCard y hệt mainFormStyle của bạn (Trắng đặc, bóng mờ 0.2)
const mainTableCard = { 
    width: '100%', 
    maxWidth: '1000px', 
    height: '90%', 
    backgroundColor: '#fff', // Trắng đặc, không dùng rgba mờ ở đây
    borderRadius: '30px', 
    padding: '30px', 
    boxShadow: '0 15px 35px rgba(0,0,0,0.2)', // Bóng đậm chuẩn
    display: 'flex', 
    flexDirection: 'column' 
};

const thStyle = { padding: '15px', color: '#8b5e5e', fontSize: '13px', fontWeight: 'bold' };
const tdRoom = { padding: '15px', fontSize: '24px', fontWeight: '900', color: '#333' };
const tdIssue = { padding: '15px', color: '#444' };

const statusSelectStyle = (s) => ({
    padding: '8px 12px', borderRadius: '12px', border: 'none', fontWeight: 'bold', cursor: 'pointer',
    backgroundColor: s === 'pending' ? '#fdf3f3' : s === 'processing' ? '#fff4e5' : '#e6f4ea',
    color: s === 'pending' ? '#8b5e5e' : s === 'processing' ? '#664d03' : '#1e7e34',
    fontSize: '13px'
});

const statusMsg = { textAlign: 'center', color: '#8b5e5e', fontWeight: '500', marginTop: '100px' };
const emptyState = { textAlign: 'center', color: '#bbb', marginTop: '100px' };

export default QuanLyBaoTri;
